var e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Kant-en-klare Klipper-configblokken en macro's - startsequenties, filamentbeheer, input shaping, bed mesh en meer. Kopieer er een en plak die in je printer.cfg (de Config Editor is een goede plek om te plakken).`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Help`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Over configsjablonen`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Sluiten`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Hoe te gebruiken`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Filter op categorie om een macro of configblok te vinden.`}},{t:0,b:{t:2,i:[{t:3}],s:`Lees de beschrijving en welke secties nodig zijn.`}},{t:0,b:{t:2,i:[{t:3}],s:`Kopieer het sjabloon, plak het in je config en pas de waarden aan.`}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:`Wat dit zijn`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Een samengestelde set veelgebruikte Klipper-bouwstenen: gcode_macros (PRINT_START, PAUSE/RESUME, filament laden/lossen, M600) en configsecties ([input_shaper], [bed_mesh], [firmware_retraction], …). Het zijn startpunten - lees ze door en stem ze af op je machine.`}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:`Een sjabloon invoegen`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Kopieer een sjabloon en plak het in je printer.cfg - de Raw-weergave van de Config Editor is een handige plek. Na opslaan wordt het toegepast met een firmwareherstart. Controleer altijd eerst de waarden; de standaardwaarden hier zijn zinvol maar niet afgestemd op jouw printer.`}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`Vereiste secties`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Elk sjabloon vermeldt de configsecties die het definieert of nodig heeft. Als een sectie al in je config bestaat, voeg dan de sleutels samen in plaats van een duplicaat te plakken (een dubbele sectie wordt bij het opstarten geweigerd).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Woordenlijst`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:`Sjabloon`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een kant-en-klaar fragment Klipper-config of macro-G-code dat je in printer.cfg kopieert.`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`gcode_macro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een benoemd commando dat je in de config definieert (bijv. PRINT_START) en dat een reeks G-code uitvoert.`}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:`Sectie`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een configblok tussen [haken], bijv. [bed_mesh] - de eenheid waarin Klipper-configuratie is gegroepeerd.`}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:`Categorie`}},all:{t:0,b:{t:2,i:[{t:3}],s:`Alle categorieën`}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:`Kopiëren`}},copied:{t:0,b:{t:2,i:[{t:3}],s:`Gekopieerd!`}},requires:{t:0,b:{t:2,i:[{t:3,v:`Secties: `},{t:4,k:`sections`}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` sjablonen`}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Sjablonen laden…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Kon de sjablonen niet laden.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Geen sjablonen in deze categorie.`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`Opnieuw proberen`}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:`Configblokken`}},macros:{t:0,b:{t:2,i:[{t:3}],s:`Macro's`}}}}};export{e as default};